// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/summary", wrapper.GetAlertSummary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/configurations", wrapper.ListAlertConfigurations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/configurations/{id}", wrapper.GetAlertConfiguration)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/alerts/configurations/preview", wrapper.PreviewAlertConfiguration)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/alerts/commands/preview", wrapper.PreviewAlertCommand)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/alerts/trial", wrapper.TrialAlertPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/instances", wrapper.ListAlertInstances)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/history", wrapper.ListAlertHistory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/deliveries", wrapper.ListAlertDeliveries)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/instances/{id}", wrapper.GetAlertInstance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/deliveries/{id}", wrapper.GetAlertDelivery)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/alerts/instances/{id}/handle", wrapper.HandleAlertInstance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/alerts/history/export", wrapper.ExportAlertHistory)
	})

	return r
}

